import{_ as i,H as a,f as t,i as p}from"./chunks/framework.BH2BK_3i.js";const g=JSON.parse('{"title":"21 | 畅想：五年后的AI产品长什么样？","description":"","frontmatter":{},"headers":[{"level":2,"title":"AI 企业管理类软件的未来：Day.ai","slug":"ai-企业管理类软件的未来-day-ai","link":"#ai-企业管理类软件的未来-day-ai","children":[]},{"level":2,"title":"办公类软件的未来：Notion AI","slug":"办公类软件的未来-notion-ai","link":"#办公类软件的未来-notion-ai","children":[]},{"level":2,"title":"AI 硬件的未来在哪里，Meta-Ray-ban 眼镜是吗？","slug":"ai-硬件的未来在哪里-meta-ray-ban-眼镜是吗","link":"#ai-硬件的未来在哪里-meta-ray-ban-眼镜是吗","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"课后题：","slug":"课后题","link":"#课后题","children":[]},{"level":2,"title":"参考","slug":"参考","link":"#参考","children":[]}],"relativePath":"成为AGI产品经理/21｜畅想：五年后的AI产品长什么样？.md","filePath":"成为AGI产品经理/21｜畅想：五年后的AI产品长什么样？.md","lastUpdated":1795557342000}'),n={name:"成为AGI产品经理/21｜畅想：五年后的AI产品长什么样？.md"};function o(s,e,l,r,h,A){return a(),t("div",null,[...e[0]||(e[0]=[p('<h1 id="_21-畅想-五年后的ai产品长什么样" tabindex="-1">21 | 畅想：五年后的AI产品长什么样？ <a class="header-anchor" href="#_21-畅想-五年后的ai产品长什么样" aria-label="Permalink to &quot;21 | 畅想：五年后的AI产品长什么样？&quot;">​</a></h1><p>你好，我是产品二姐。</p><p>在开篇词当中，二姐拿出 Gartner 的一张图来体现 AIGC 的发展趋势；今天，在我们展望未来这节课，二姐再拿出这张图大家一起看一下。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/21/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/21/1.png" alt=""></a></p><p>Gartner 的这个曲线是多次历史经验总结的结果，图中的曲线走势告诉我们两点：</p><ul><li><p>一是 AIGC 技术在未来 2～5 年走向成熟。</p></li><li><p>二是即使技术走向成熟，与媒体不切实际的 Hype 仍然有一定距离。</p></li></ul><p>尤其是第二点，在 AI 发展的历史上，就曾经多次出现过这样的 Hype。比如 1970 年，图灵奖得主 Marvin Minsky 在美国 Life 杂志的访谈中提到： “未来 3～8 年，机器将会达到人类智力的平均水平，并且如果幸运的话，人类可能会成为机器的宠物。”[参考 1]，现在回头看当时的言论具有一定的误导性。再比如我们在国庆加餐的那节课提到过，1971 年，JohnMcCarthy 被授予图灵奖的时候，发表了《人工智能的通用性》的演讲，但在 1986 年，他也公开承认自己当时的想法过于乐观。</p><p>其实，二姐在过去一年多的时间里，通过自己做产品的经历，也从一个 AI 憧憬者，慢慢过渡到一个 AI 实践者。</p><p>所以，在这节课的内容“五年后 AI 产品的畅想”里，没有不切实际的幻想，而是有根据地按照目前的技术成熟度聊一下未来五年可能会发生什么样的变化。具体我会分成三类产品，每类产品会选择一个代表性的案例来看。</p><ul><li><p>一是 AI 的企业级管理类软件，我选择的案例是一款 AI Native 的 CRM 软件 Day.ai。</p></li><li><p>二是 AI 的办公类软件，我选用了最先采纳 AI 功能的办公类软件 Notion AI 和大家分享。</p></li><li><p>三是 AI 的硬件，我会用 2024 年度预计销量达到 200 万 Meta-Ray-Ban 眼镜展开说说。</p></li></ul><p>这些知识可以在以下三个方面帮助到你：</p><ul><li><p>一是可能会激发你在现有的产品当中注入让人眼前一亮的新特性。</p></li><li><p>二是能帮你甄别一个脚踏实地但又有长远眼光的老板或者合伙人，而不是一个漫无边际、只觉得是你不行而不是 AI 不行的老板。</p></li><li><p>三是带你树立一个长期、有效的系统成长路径，而不是完成短期的目标。因为这些内容会让你在媒体的炮火声中冷静下来，思考你今天你应该加入什么样的公司，它能为你的下一份工作带来哪些收益。</p></li></ul><p>好了，让我们开始吧。</p><h2 id="ai-企业管理类软件的未来-day-ai" tabindex="-1">AI 企业管理类软件的未来：Day.ai <a class="header-anchor" href="#ai-企业管理类软件的未来-day-ai" aria-label="Permalink to &quot;AI 企业管理类软件的未来：Day.ai&quot;">​</a></h2><p>Day.ai 是一家初创公司，最近拿到红杉的 400 万美元的融资。你可能完全没有听说过 day.ai，但你可能听说过 CRM 独角兽 Hubspot。Hubspot 在 2006 年，颇具预见眼光地以内容营销CRM 为起点，乘着移动互联网的大浪潮而崛起，成为美国仅次于 Salesforce 的新型 CRM 厂商。</p><p>而 Day.ai 的创始人 Christopher O’Donnell 正是前任 Hubspot 首席产品官，那么O’Donnell 会不会延续他在 Hubspot 的精神，在 AI 的风潮中成为又一轮新型的 CRM 厂商呢？我们来看看他正在创办的 Day.ai。</p><p>Day.ai 产品还没有正式公开发布，但它们官网上的一张图片，清晰地描述了未来 Day.ai 最核心的产品特性。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/21/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/21/2.png" alt=""></a></p><p>我们一起来理解一下这张图片背后的理念。</p><p>图的左侧是现有 CRM 的表格化结构，这对于做过 CRM 产品的同学来说是再熟悉不过了。在互联网时代，大多数的 CRM 是围绕客户生命周期的不同阶段做信息记录、整理、分析，最常见的表现形态就是各种图表。比如下图是国内最大的 CRM 软件公司纷享销客一张截图。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/21/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/21/3.png" alt=""></a></p><p>而对企业来说，这类 CRM 满足了企业内部不同层级的人员诉求，比如：</p><ul><li><p>对于一线销售来说：它可以记录客户信息，占有客户资源，提供自己的业绩证据。</p></li><li><p>对于中层管理来说：可以协助分配客户资源，管理销售团队业绩考核。</p></li><li><p>对于高层管理来说：它能够查看成交总额，掌握产品销量。</p></li></ul><p>你看，这里的 CRM 大多是查看、分析、跟踪进度的，而实际上销售与客户的关系是通过各种各样的文字、沟通、会议建立起来的。所以这里的 CRM 更像是企业为了适应电子化管理而附属诞生的工具，它的功能更侧重 CRM 中的“Management”。</p><p>但在我看来，真正理想的 CRM 应该满足更深层次的需求：</p><ul><li><p>对高层管理来说，好的 CRM 要能洞察客户原始诉求，以便做出正确战略决策，从而提高成交金额。</p></li><li><p>对于中层管理来说，CRM 要能帮助提高团队的销售能力。</p></li><li><p>对于一线销售来说，可以帮销售拉近客户关系，为自己提升销售业绩。</p></li></ul><p>但我们很难从冷冰冰的数字和表格记录中获得这些，那么 day.ai 是怎么满足这种诉求的呢？咱们看图片右边，它以页面、文字、视频等方式，让销售与客户的关系在沟通中拉近距离，用他们自己的话说就是：</p><ul><li>Day.ai 将 CRM、会议助理和知识库的功能整合到一个统一的产品中，让您和您的团队能够了解客户的实际需求。</li></ul><p>Day.ai 从形式上弱化了表格式、结果导向的形态，非常合理地利用了大语言模型的信息理解、提取、整理、分析能力，能自动捕捉和分析对话数据，整合了会议助理和知识库的功能，主动查询客户洞察，并给出销售建议，即它所说的“Have conversations， let AI do the rest”。而这些信息恰好可以满足上述的三个深层次诉求。</p><p>相比传统 CRM，Day.ai 更侧重 CRM 中的“Relationship”。为了更形象地表述 Day.ai 的创新，我用一句话描述就是：</p><p>“从表格式信息进化到沟通式信息，弱化管理，回归关系”。</p><p>那 Day.ai 对我们又对我们有哪些启发呢？ 我们可以简单延伸到其他的管理类场景。比如，你可以思考：现有的软件研发管理工具是否也可以借鉴这个思想？</p><p>我们拿软件开发中的一个环节–Bug 管理来说。一个测试工程师真正有效的工作就是真正运行软件的那段时间。但这段时间，每次发生 Bug，TA 都要停下来记录，这种方式不仅消耗时间，还打断了测试工程师的心流体验。</p><p>如果我们把上述记录工作变为页面、文字、视频形式， 测试工程师采用录屏、语音的方式记录整个测试过程，如果发生 Bug，测试工程师只需要语音强调一下。然后在录屏之后，由大语言模型根据录屏操作、语音输入、结合多模态识别，自动拆分成不同的测试执行记录或者Bug，并把每个记录变成一个网页，这样的记录到了开发小哥的手里，也会是一目了然。</p><p>你看，这种“心流式”的操作方式会不会改变你对“管理类”软件的设计思路呢？实际上，类似的理念我们也看到被使用在了其他领域，比如在 YC 2024 的一个项目InspectMind AI 就用类似的方式完成了建筑工地现场考察生成报告的过程。</p><p>聊完流程管理类的 CRM 软件，我们来看看主要用于知识管理的办公软件。</p><h2 id="办公类软件的未来-notion-ai" tabindex="-1">办公类软件的未来：Notion AI <a class="header-anchor" href="#办公类软件的未来-notion-ai" aria-label="Permalink to &quot;办公类软件的未来：Notion AI&quot;">​</a></h2><p>相较于 Day.ai，我相信不少同学都知道 Notion 这款办公软件。Notion 可以说是互联网时代真正意义上改变了传统微软 Office 套件的办公软件。举个例子，在 Notion 之前，Office word 的文档是用不同的格式来代表文档里的不同内容；而 Notion 将这些不同内容定义为一个个模块， 比如标题 1、标题 2、图片模块、代码模块，用户可以自由拖动这些模块排版、汇总、统计。</p><p>这种“乐高模块化的思维”让 Notion 成为 All-in-one 的软件，适用于任何组织，就像是办公软件中的宜家。现在大家所看到的飞书文档、钉钉等也都借鉴了 Notion 的模块化思维。</p><p>当大语言模型来临之时，Notion 早在 2023 年 2 月 23 日就率先发布了 Notion AI，比微软发布Office 365 Copilot 还要早 20 多天。那么发展了一年多，现在我们能在 Notion 中看到什么样的 AI 的特性呢？</p><p>在这里，我会先把知识管理分为知识收集→知识理解→知识生产这三个环节，然后再一一检验目前 Notion AI 哪些环节正在进行，哪些环节还没开始？对于那些还没开始的环节，我们可以思考它是否能在不久的将来诞生？</p><p>环节一：知识获取</p><p>这个环节最难的是如何保证记录的完整性。想想在工作中，我们的信息触点非常多，而它们大部分都没有记录在 Notion 里。那么，Notion AI 将如何获取这些信息呢？</p><p>2024 年 9 月 25 日，Notion AI 发布了 New AI connectors，支持用户在 Notion AI 的入口中询问来自其他工具的信息，这些工具目前包括 Slack、Google，未来会有更多的信息源。</p><p>而这种强大的信息整合收集能力是建立在 Notion 已经集成的 100 多个 SAAS 工具基础之上的。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/21/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/21/4.png" alt=""></a></p><p>可以想象，未来 5 年，Notion AI 会越来越多地集成这些软件，让知识获取更完整。遗憾的是，我们在国内并没有北美开放的 SaaS 生态，这也许在未来会给中国办公类软件智能化带来一些阻碍。</p><p>环节二：知识理解</p><p>知识理解让工具来做，你可能会有一个疑问：如何能判断工具是否真正理解了给定的知识呢？其实，这个问题在办公场景中，不必探究到脑科学或者心理科学的层面。我们联想一下英语考试中的阅读理解题就明白了，如果 Notion 可以在给定阅读材料后，正确回答相关问题，那就意味着它理解了知识。</p><p>你可以简单地把知识理解能力转换成 AI 搜索问答这样的功能，在 Notion 里叫“万事问 AI”。它能对指定数据源进行问答，并且二姐能真切地感受到 Notion AI 的回答准确率越来越高了，相信类似的功能也会越来越完善。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/21/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/21/5.png" alt=""></a></p><p>其实你也可能意识到了，这个功能本质上和我们在第三个实战案例“企业级 AI 搜索”本质是一样的。如果在 AI 搜索的意图识别、Query 重写、知识库管理、检索结果合成上做到极致，就能具备较好的知识理解能力。</p><p>这一点，我认为 5 年后，主流的办公软件都会达到较好的知识理解水平。</p><p>环节三：知识生产</p><p>和前两个环节相比，这一个环节是最难的。 知识生产会分三步走：首先是构建思路框架，然后按照思路丰富内容，最后是整理呈现。套用我们在 20 节提到的内容生产过程就是：在散点中形成体系→丰富体系的过程。</p><p>第一步是构建思路框架。就是发现散点之间的内在联系的过程，让软件从已知的信息中发现新的规律。比如二姐曾经尝试让 Notion AI 自行从十个介绍某一主题的历史文章，预测未来趋势，产生全新的知识，这是非常困难的。</p><p>第二步是按照思路丰富内容。我们让 Notion AI 在指定思维框架中丰富各部分内容，这是能够非常好地完成的，比如用户要求：找到所有笔记中提到的图灵奖得主，并列出他们的出生年月、获奖年份、核心贡献，它可以在几秒内从几万字中找到正确答案，并标明出处。</p><p>接下来就是整理呈现。我们也发现了两个小功能：</p><ol><li><p>Notion AI 支持按照用户自己的风格写作；</p></li><li><p>Notion AI 不仅能聊天，而且还会做事儿了！比如用户可以通过对话创建一个文档，且相信未来应该会支持越来越多的 Action。</p></li></ol><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/21/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/21/6.png" alt=""></a></p><p>在对知识管理的三个环节分析后，我们不妨以 Notion AI 为标杆，脚踏实地展望 5 年后办公类软件在 AI 能做到哪些事情。我总结成三句话就是：</p><ul><li><p>知识获取上，数据源越来越丰富。</p></li><li><p>知识理解上，指定数据源的 AI 回答越来越准确、有依据。</p></li><li><p>知识生产上，书写质量越来越个性化。并且未来还可以 take action，包括创建、整理（移动文件夹）。</p></li></ul><p>看完了两个软件类产品，接下来我们看看未来五年的 AI 硬件会怎么发展。</p><h2 id="ai-硬件的未来在哪里-meta-ray-ban-眼镜是吗" tabindex="-1">AI 硬件的未来在哪里，Meta-Ray-ban 眼镜是吗？ <a class="header-anchor" href="#ai-硬件的未来在哪里-meta-ray-ban-眼镜是吗" aria-label="Permalink to &quot;AI 硬件的未来在哪里，Meta-Ray-ban 眼镜是吗？&quot;">​</a></h2><p>关于硬件的展望，我想带你从两段历史中寻找端倪。</p><p>第一段历史：施乐公司的预言</p><p>1990 年代，施乐公司研究院 CTO Mark Weiser 对 21 世纪所有计算机设备的畅想，他在论文《The computer in 21st centry》[参考 4]中提到：</p><ul><li>21 世纪会有四种不同大小的计算机设备：- Pocket-size tabs—今天的手机- Page-size pads —笔记本 /pad- Large-screen displays — 投影仪- Inch-scale badge — 智能手表、手环、眼镜等可穿戴设备</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/21/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/21/7.png" alt=""></a></p><p>有很多人说，乔布斯的苹果生态产品其实就是窃取了施乐公司的想法，现在看起来不无道理。可以看到，今天我们已经拥有了投影仪、笔记本、手机，并且这三类产品已经大面积普及，对于可穿戴设备，虽然出现了各种手表、Badge 等形式，但似乎还没有大面积普及，尘埃尚未落定。</p><p>第二段历史：个人电脑诞生以来的计算机应用技术的发展历史</p><p>这段历史是二姐个人总结的。在这段历史中，依次诞生了几个技术产物：个人电脑 → 互联网→ 智能手机 → 人工智能。</p><p>其中第一项个人电脑和第三项智能手机是硬件；第二项互联网和第四项人工智能是软件。这段历史中硬件和软件交替诞生，新硬件的出现为新软件提供了物理基础和可能性，新软件的发展又推动了对更强大硬件的需求。于是技术就在这种软硬件的双驱动中走上一个又一个新台阶，我用下面这张图来表示。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/21/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/21/8.png" alt=""></a></p><p>现在，我们刚刚开始一项新软件–大语言模型 AI 在两个硬件也就是个人电脑、智能手机上的应用，而同时我们似乎还在等待一个新硬件的诞生。也许到新硬件诞生后，才有可能实现一个全新的杀手级超级软件应用吧。</p><p>那这两段历史是不是预示着：下一个现象级的硬件可能是在可穿戴领域，那么这个新硬件能在未来 5 年内诞生吗？我们来看一下现状。</p><p>当下最值得一提的可穿戴设备就是 Meta-Ray-Ban 智能眼镜。它是 2023 年 10 月发布的，预计在 2024 年底销量突破 200 万台。客观讲，这个销量不及 iPhone 1 代第一年的总销量 610万台，但远高于 10 年前 Google glasses 的销量 30 万。</p><p>而 Meta-Ray-Ban 之所以开始被用户接受，是因为它非常勇敢地抛弃了技术人对 VR 的幻想，做出了一款切实可用、人人能买得起的产品。同时又非常及时地接入了多模态大模型，能对用户所见景象做出实时解答和记录，满足了人们猎奇的诉求。</p><p>不过 Meta Ray-Ban 这类穿戴式设备的另外一个优势目前还远远未被挖掘，那就是它能实现“眼睛所到之处皆可被数字化”。想象一下，那时我们所能记录的信息可能是今天手机能记录信息的数百倍。只有这些数据被充分采集，我们才有可能为每个人建立一个第二大脑，诞生出超级个人助理。也许到那时候，我们才会诞生出一个全新的、完全想象不到的软件产品。</p><p>但在 5 年内，一个堪比 iPhone 的硬件能否诞生，我们可以拭目以待。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>最后，我们来总结一下。在冷静认识技术能力的前提之下，我们一起憧憬了未来 5 年几类 AI产品的发展。</p><ul><li><p>在管理类软件产品中，我们以 Day.ai 为代表，看到了一个 from table to page 的产品。</p></li><li><p>在办公类软件产品中，我们以 Notion AI 为代表，看到了一个数据源接入越来越丰富、问题解答会更准确、书写会越来越个性化的办公类产品。</p></li><li><p>在硬件类产品中，我们也许会看到一个可穿戴的设备能帮我们采集到更多的数据，从而诞生出来一个全新的，我们也不知道是什么样的软件类的产品，也许那是在十年之后。</p></li></ul><p>作为产品经理，乐观且务实，做出当下有用、可行的产品，跟着技术节奏一起前行，是参与和创造历史的最好时机。</p><h2 id="课后题" tabindex="-1">课后题： <a class="header-anchor" href="#课后题" aria-label="Permalink to &quot;课后题：&quot;">​</a></h2><p>今天给你留两道课后题。</p><p>第一题：</p><p>参考 Day.ai 的“从表格式信息进化到沟通式信息”的理念，想想在你的工作当中有哪些管理类软件同样适用于这种理念呢？</p><p>第二题：</p><p>大家也可以思考：</p><ul><li><p>一方面我们看到 Day.ai 开始尝试在管理类软件中生产出非结构的页面，文字等内容，实现结构化到非结构化的转变；</p></li><li><p>另一方面 AI 办公软件可以让用户从非结构化的文字中总结出大量的图表结构化数据，实现非结构化向结构化的转变。</p></li></ul><p>那么，大语言模型这种从结构化到非结构化的打通能力是不是能让大家在工作场景中产生新的链接，诞生新洞察呢？</p><p>欢迎你在评论区留言，如果觉得有所收获，也可以把课程分享给更多的朋友一起学习。我们下节课见！</p><h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h2><p>参考 1：<a href="https://forums.spacebattles.com/threads/in-three-to-eight-years-we-will-have-a-machine-with-the-intelligence-of-a-human-being.375654/" target="_blank" rel="noreferrer">https://forums.spacebattles.com/threads/in-three-to-eight-years-we-will-have-a-machine-with-the-intelligence-of-a-human-being.375654/</a></p><p>参考 2：介绍 day.ai <a href="https://day.ai/sequoia-backs-ai-native-crm" target="_blank" rel="noreferrer">https://day.ai/sequoia-backs-ai-native-crm</a></p><p>参考 3：Notion AI 2.45 发布 <a href="https://www.notion.com/releases/2024-09-25" target="_blank" rel="noreferrer">https://www.notion.com/releases/2024-09-25</a></p><p>参考 4：施乐公司研究院 CTO Mark Weiser《The computer in 21st centry》<a href="https://web.stanford.edu/class/cs240e/papers/weiser.pdf" target="_blank" rel="noreferrer">https://web.stanford.edu/class/cs240e/papers/weiser.pdf</a></p>',98)])])}const u=i(n,[["render",o]]);export{g as __pageData,u as default};
